import React, { useState } from 'react';     
import './LoginPage.css';

const LoginPage = () => {
  const [email, setEmail] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Email submitted:', email);
  };

  const handleStaffAdminLogin = () => {
    console.log('Navigate to staff/admin login');
    // Có thể navigate đến trang login riêng cho staff/admin
  };

  return (
    <div className="login-page">
      <div className="login-container">
        <div className="logo-section">
          <img src="/LEAF.png" alt="LEAF" className="logo" />
        </div>
        
        <div className="login-content">
          <h1 className="login-title">Đăng nhập</h1>
          <p className="login-description">
            Nhập email của bạn để chúng tôi gửi cho bạn mã xác minh
          </p>
          
          <form onSubmit={handleSubmit} className="login-form">
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="email-input"
              required
            />
            
            <button type="submit" className="continue-button">
              Tiếp tục
            </button>
          </form>
          
          <div className="links-section">
            <button className="policy-link" onClick={() => console.log('Privacy policy')}>
              Chính sách quyền riêng tư
            </button>
            <button className="terms-link" onClick={() => console.log('Terms of service')}>
              Điều khoản dịch vụ
            </button>
          </div>
          
          <div className="staff-admin-section">
            <button 
              className="staff-admin-link" 
              onClick={() => console.log('Navigate to staff/admin login')}
            >
              Đăng nhập Staff và admin
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
